@startuml

class User {
  + ID : int
  + Name : string
  + Email : string
  + DateOfBirth : date
}

class Account {
  + AccountNumber : int
}

class BusinessAccount {
  + CompanyName : string
  + MonthlyFee : double
}

class PersonalAccount {
}

class Page {
  + PageName : string
  + NumberOfVisits : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "1" Account
Account --|> BusinessAccount
Account --|> PersonalAccount
BusinessAccount "1" -- "*" Page
PersonalAccount "1" -- "*" Page
PersonalAccount "0..*" -- "0..*" Page : privilege
AdvertisementPage --|> Page

@enduml

